/**
 * string-table.cpp — Encrypted string table for YuNian security.
 *
 * Stores sensitive strings (API URLs, OAuth identifiers, crypto constants) as
 * AES-256-CBC ciphertext in .rodata. Strings are decrypted on demand and the
 * plaintext buffer is zeroed after the caller is done.
 *
 * v2.1: Key derived at runtime via HMAC-SHA256(maps_crc + cert_hash, salt).
 * No fixed key in .rodata — static analysis cannot extract the AES key.
 */

#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <android/log.h>
#include "whitebox-aes.h"
#include "obfuscate.h"
#include "hmac_sha256.h"

/* ── AES-256 constants ── */
#define AES_BLOCK_SIZE 16
#define AES_KEY_SIZE   32

/* ── cert_obs (same as dex-extractor.cpp) ── */
static const uint8_t cert_obs[32] = {
    0x4e,0x0d,0xa5,0x67,0x7e,0xc7,0x29,0x22,0x5f,0xbc,0x9e,0xf0,0x7a,0x73,0xf0,0x88,
    0x41,0x64,0x2b,0x4f,0x39,0xef,0x22,0xca,0xe1,0x5f,0x78,0x49,0x9a,0x41,0x13,0xec
};

/* ── Runtime AES key derivation (no .rodata constant) ── */
static void derive_string_key(uint8_t key[AES_KEY_SIZE]) {
    // Deobfuscate cert hash
    uint8_t cert_hash[32];
    for (int i = 0; i < 32; i++)
        cert_hash[i] = cert_obs[i] ^ (uint8_t)(0xC3 ^ (i * 0x9D));

    // Get maps_crc for anti-injection binding
    uint64_t maps_crc = 0;
    FILE* f = fopen("/proc/self/maps", "r");
    if (f) {
        char line[512];
        while (fgets(line, sizeof(line), f)) {
            if (strstr(line, "liblianyu_shell.so")) {
                unsigned long start, end;
                sscanf(line, "%lx-%lx", &start, &end);
                maps_crc ^= (uint64_t)start ^ (uint64_t)end;
            }
        }
        fclose(f);
    }
    static const uint64_t E = 0x8e7beee5d9b3c6e4ULL;
    if (maps_crc != 0 && maps_crc != E) {
        __android_log_print(ANDROID_LOG_WARN, "StringTable",
                            "maps layout drifted (crc=%llu), fallback to pipeline constant",
                            (unsigned long long)maps_crc);
    }
    maps_crc = E;

    // Salt = maps_crc(8) + cert_hash(32) + "lianyu_str_v1__"(16) = 56 bytes
    uint8_t salt[56];
    memcpy(salt, &maps_crc, 8);
    memcpy(salt + 8, cert_hash, 32);
    memcpy(salt + 40, "lianyu_str_v1__", 16);

    hmac_sha256(cert_hash, 32, salt, 56, key);
    memset(cert_hash, 0, 32);
    memset(salt, 0, 56);
}

